import Foundation

/// One stored conversation from a coding agent.
public struct Session: Identifiable, Hashable, Sendable {
    public let id: String
    public let source: SessionSource
    /// The name given with a rename, or generated by the agent.
    public let name: String?
    /// The directory the session ran in, when the transcript records one.
    public let projectPath: String?
    public let firstMessage: String?
    public let updatedAt: Date
    public let size: Int64
    public let fileURL: URL
    /// True while a running agent owns this session.
    public let isActive: Bool

    /// The best label for the session, if it has one.
    public var title: String? { name ?? firstMessage }

    /// Sessions in use can't be selected or deleted.
    public var isDeletable: Bool { !isActive }

    /// Whether the session was last used more than `days` days before `now`.
    public func isOlder(thanDays days: Int, now: Date = Date()) -> Bool {
        now.timeIntervalSince(updatedAt) > TimeInterval(days) * 24 * 60 * 60
    }

    public init(
        id: String,
        source: SessionSource,
        name: String? = nil,
        projectPath: String?,
        firstMessage: String?,
        updatedAt: Date,
        size: Int64,
        fileURL: URL,
        isActive: Bool
    ) {
        self.id = id
        self.source = source
        self.name = name
        self.projectPath = projectPath
        self.firstMessage = firstMessage
        self.updatedAt = updatedAt
        self.size = size
        self.fileURL = fileURL
        self.isActive = isActive
    }
}
